const input = $input.first().json;
const payload = input.body ?? input;
const alerts = Array.isArray(payload.alerts) ? payload.alerts : [];
return alerts
  .filter((alert) => alert.status === 'firing')
  .map((alert) => ({
    json: {
      alertname: alert.labels?.alertname ?? 'UnknownAlert',
      severity: alert.labels?.severity ?? 'warning',
      service: alert.labels?.service ?? alert.labels?.job ?? 'unknown',
      summary: alert.annotations?.summary ?? 'No summary provided',
      description: alert.annotations?.description ?? 'No description provided',
      instance: alert.labels?.instance ?? 'unknown',
      startsAt: alert.startsAt ?? new Date().toISOString(),
      fingerprint: alert.fingerprint ?? 'unknown',
      generatorURL: alert.generatorURL ?? '',
      traceId: alert.labels?.trace_id ?? alert.annotations?.trace_id ?? 'n/a'
    }
  }));

